"""Selectable food icons, excluding hotkeys and surrounding HUD."""
FOOD_OPTIONS = [('none','선택 안 함'),('snack','여행자 간식 (갈색 빵모양)'),('egg','삶은 달걀')]
FOOD_TEMPLATES = {'f_egg': {'png': '', 'roi': [65, 45, 250, 180], 'threshold': 0.9, 'scales': [0.55, 0.65, 0.75, 0.85, 0.95, 1.0, 1.05, 1.15, 1.25, 1.35]}}


def selected_food_kind(settings):
    kind=settings.get('food_kind','snack' if settings.get('food',True) else 'none')
    return kind if kind in dict(FOOD_OPTIONS) else 'none'
